{
  "name": "Basic QA Suite",
  "description": "Tests the agent's ability to answer factual questions",
  "scoring_method": "contains"
}

{
  "name": "Capital of France",
  "input_message": "What is the capital of France?",
  "expected_output": "Paris",
  "tags": ["geography", "factual"]
}

{
  "name": "web_search",
  "description": "Search the web for information",
  "framework": "deepagents",
  "tool_type": "custom",
  "category": "search",
  "schema": {
    "type": "function",
    "function": {
      "name": "web_search",
      "description": "Search the web",
      "parameters": {
        "type": "object",
        "properties": {
          "query": { "type": "string", "description": "Search query" }
        },
        "required": ["query"]
      }
    }
  },
  "auth_config": {
    "api_key": "your-search-api-key"
  }
}

{
  "name": "Remote Tools Server",
